double exahype2::elastic::ElasticSolver::maxEigenvalue(
  [[maybe_unused]] const double* __restrict__ Q, // Q[7+10]
  [[maybe_unused]] const tarch::la::Vector<Dimensions, double>&      x,
  [[maybe_unused]] const tarch::la::Vector<Dimensions, double>&      h,
  [[maybe_unused]] double                                            t,
  [[maybe_unused]] double                                            dt,
  [[maybe_unused]] int                                               normal
) {
  logTraceInWith3Arguments("maxEigenvalue(...)", x, t, normal);

  double cp = Q[8];
  double cs = Q[9];

  double q_x = Q[11];
  double q_y = Q[12];

  double r_x = Q[13];
  double r_y = Q[14];

  double maxEigenvalue = 1.0;
  maxEigenvalue = std::max(maxEigenvalue, std::sqrt(q_x*q_x + q_y*q_y)*cp);
  maxEigenvalue = std::max(maxEigenvalue, std::sqrt(q_x*q_x + q_y*q_y)*cs);
  maxEigenvalue = std::max(maxEigenvalue, std::sqrt(r_x*r_x + r_y*r_y)*cp);
  maxEigenvalue = std::max(maxEigenvalue, std::sqrt(r_x*r_x + r_y*r_y)*cs);

  return maxEigenvalue;

  logTraceOut("maxEigenvalue(...)");
}



void exahype2::elastic::ElasticSolver::flux(
  [[maybe_unused]] const double* __restrict__ Q, // Q[7+10]
  [[maybe_unused]] const tarch::la::Vector<Dimensions, double>&      x,
  [[maybe_unused]] const tarch::la::Vector<Dimensions, double>&      h,
  [[maybe_unused]] double                                            t,
  [[maybe_unused]] double                                            dt,
  [[maybe_unused]] int                                               normal,
  [[maybe_unused]] double* __restrict__       F // F[7]
) {

  double sigma_xx=Q[2];
  double sigma_yy=Q[3];
  double sigma_xy=Q[4];

  double jacobian=Q[7+3];

  double q_x = Q[7+4];
  double q_y = Q[7+5];
  double r_x = Q[7+6];
  double r_y = Q[7+7];
  
  switch(normal){
    case 0:
      F[0] = -jacobian*(q_x*sigma_xx+q_y*sigma_xy);
      F[1] = -jacobian*(q_x*sigma_xy+q_y*sigma_yy);
      break;
    case 1:
      F[0] = -jacobian*(r_x*sigma_xx+r_y*sigma_xy);
      F[1] = -jacobian*(r_x*sigma_xy+r_y*sigma_yy);
      break;
  }

  F[2] = 0.0;
  F[3] = 0.0;
  F[4] = 0.0;
  F[5] = 0.0;
  F[6] = 0.0;


}



void exahype2::elastic::ElasticSolver::nonconservativeProduct(
  [[maybe_unused]] const double* __restrict__ Q, // Q[7+10]
  [[maybe_unused]] const double* __restrict__ deltaQ, // deltaQ[7+10]
  [[maybe_unused]] const tarch::la::Vector<Dimensions, double>&      x,
  [[maybe_unused]] const tarch::la::Vector<Dimensions, double>&      h,
  [[maybe_unused]] double                                            t,
  [[maybe_unused]] double                                            dt,
  [[maybe_unused]] int                                               normal,
  [[maybe_unused]] double* __restrict__       BTimesDeltaQ // BTimesDeltaQ[7]
) {

  double q_x = Q[7+4];
  double q_y = Q[7+5];
  double r_x = Q[7+6];
  double r_y = Q[7+7];

  double u_q=deltaQ[0];    
  double v_q=deltaQ[1];

  double u_r=deltaQ[0];
  double v_r=deltaQ[1];

  BTimesDeltaQ[0] = 0.0;
  BTimesDeltaQ[1] = 0.0;
  switch(normal){
    case 0:
      BTimesDeltaQ[2] = -q_x*u_q;
      BTimesDeltaQ[3] = -q_y*v_q;
      BTimesDeltaQ[4] = -(q_y*u_q+q_x*v_q);
      break;
    case 1:
      BTimesDeltaQ[2] = -r_x*u_r;
      BTimesDeltaQ[3] = -r_y*v_r;
      BTimesDeltaQ[4] = -(r_y*u_r+r_x*v_r);
      break;
  }
  BTimesDeltaQ[5] = 0.0;
  BTimesDeltaQ[6] = 0.0;



}



